package algorithm_study;

import java.util.*;
import java.io.*;

public class finding_the_mode_1204 {
	static BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); 
	static int[] arr;
	static StringTokenizer st;
	
	public static void main(String[] args) throws IOException {
		int case_t = Integer.parseInt(br.readLine());
		
		for (int t = 0; t < case_t; t++) {
			 arr = new int[101];
			 
			 br.readLine();
			 st = new StringTokenizer(br.readLine());
			 
			 // 점수 빈도 구하기
			 for (int i = 0; i < 1000; i ++) {
				 int student_score = Integer.parseInt(st.nextToken());
				 arr[student_score] += 1;
			 }
			 
			 // 최고 값의 index 찾기
			 int max_index = 0;
			 int max_frequency = 0;
			 for (int i = 0; i < 101; i ++) {
				 if (max_frequency <= arr[i]) {
					 max_frequency = arr[i];
					 max_index = i;
				 }
			 }
			 
			 System.out.println("#" + (t + 1) + " " + max_index);
		}
	}
}

//이해
/*
최빈수 값을 구하는 문제이다
*/

//로직 (논리 + 코드 레벨)
/*
size 101의 배열을 만든다. 배열을 모두 0으로 초기화한다.
1000개의 학생 점수를 읽을 때 점수를 index로 사용한 뒤 접근된 값에 +1을 한다.
1000개의 학생 점수를 다 읽은 뒤에 배열을 sort한 뒤 max_index를 구한다.
max_index가 두 개라면 그 중 max_index 값이 높은 쪽을 출력한다.	
*/

